const norm = value => String(value ?? '')
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[إأآ]/g, 'ا').replace(/ة/g, 'ه').replace(/ى/g, 'ي').replace(/ـ/g, '')
  .trim();
const arr = value => Array.isArray(value) ? value : (value == null || value === '' ? [] : String(value).split(/[,،|]/).map(x => x.trim()).filter(Boolean));
