function mergeLanguageCatalog() {
  const add = ZAAD_LANGUAGE_CERT_COURSES || [];
  if (!Array.isArray(FALLBACK_DATA.courses)) FALLBACK_DATA.courses = [];
  const existing = new Set(FALLBACK_DATA.courses.map(x => String(x.slug || '')));
  for (const item of add) if (!existing.has(String(item.slug))) FALLBACK_DATA.courses.push(item);
}
mergeLanguageCatalog();

function debounce(fn, delayMs) {
  let timeoutId;
  return (...args) => {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => fn(...args), delayMs);
  };
}

function escapeHtml(v) {
  return String(v ?? '').replace(/[&<>'"]/g, c => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    "'": '&#39;',
    '"': '&quot;'
  } [c]));
}

function showSuggestions() {
  const box = $('search-suggestions');
  if (!box) return;
  const q = norm(state.searchQuery);
  if (!q) {
    box.classList.add('hidden');
    els.search.setAttribute('aria-expanded', 'false');
    return;
  }
  const all = uniqueDisplay([...state.opportunities, ...state.courses, ...state.platforms]);
  const matches = all.filter(x => smartSearchMatch(x, q)).slice(0, 7);
  const related = Object.entries(SEARCH_ALIASES).filter(([key, values]) => key.includes(q) || values.some(v => v.includes(q))).map(([key]) => key).slice(0, 4);
  let html = '';
  if (related.length) {
    html += '<div class="suggestion-head">عمليات بحث مرتبطة</div>';
    html += related.map(x => `<button class="suggestion-item" type="button" data-suggestion-query="${escapeHtml(x)}"><span class="suggestion-icon">⌕</span><span class="suggestion-main"><strong>${escapeHtml(x)}</strong><span>بحث ذكي في المنح والكورسات والفرص والمنصات</span></span><span class="suggestion-arrow">↵</span></button>`).join('');
  }
  if (matches.length) {
    html += '<div class="suggestion-head">نتائج سريعة</div>';
    html += matches.map(item => {
      const t = typeOf(item);
      return `<button class="suggestion-item" type="button" data-suggestion-id="${escapeHtml(item.id)}" data-suggestion-type="${escapeHtml(t)}"><span class="suggestion-icon">${ICONS[t] || '✨'}</span><span class="suggestion-main"><strong>${escapeHtml(item.title || item.name)}</strong><span>${escapeHtml(LABELS[t] || t)}${item.country ? ` • ${escapeHtml(item.country)}` : ''}</span></span><span class="suggestion-arrow">›</span></button>`;
    }).join('');
  }
  if (!html) html = '<div class="suggestion-head">لا توجد نتائج قريبة — جرّب اسم دولة أو لغة أو مجال آخر.</div>';
  box.innerHTML = html;
  box.classList.remove('hidden');
  els.search.setAttribute('aria-expanded', 'true');
  box.querySelectorAll('[data-suggestion-query]').forEach(btn => btn.addEventListener('click', () => {
    state.searchQuery = btn.dataset.suggestionQuery;
    els.search.value = state.searchQuery;
    state.visibleCount = 12;
    box.classList.add('hidden');
    els.search.setAttribute('aria-expanded', 'false');
    render();
  }));
  box.querySelectorAll('[data-suggestion-id]').forEach(btn => btn.addEventListener('click', () => {
    const id = String(btn.dataset.suggestionId);
    const type = btn.dataset.suggestionType;
    const source = type === 'platform' ? state.platforms : type === 'course' ? state.courses : state.opportunities;
    const item = source.find(x => String(x.id) === id);
    if (item) {
      box.classList.add('hidden');
      els.search.setAttribute('aria-expanded', 'false');
      type === 'platform' ? platformModal(item) : window.location.href = `/detail.html?type=${encodeURIComponent(type)}&id=${encodeURIComponent(item.id)}`;
    }
  }));
}

function renderSkeletons() {
  els.grid.innerHTML = Array.from({
    length: 6
  }, () => '<div class="skeleton"></div>').join('');
}

