function searchTerms(query) {
  const q = norm(query);
  if (!q) return [];
  const tokens = q.split(/\s+/).filter(Boolean);
  return [...new Set(tokens.flatMap(t => [t, ...(SEARCH_ALIASES[t] || [])].map(norm)))];
}

function asText(item) {
  const type = typeOf(item);
  const label = LABELS[type] || '';
  const raw = [item.title, item.name, item.description, item.organization, item.platform_name, item.country, item.category, item.language, item.level, item.education_level, item.funding_type, item.certificate_type, item.age_min, item.age_max, label, ...arr(item.categories), ...arr(item.keywords)].filter(Boolean).join(' ');
  const expanded = searchTerms(raw.split(/\s+/).slice(0, 40).join(' '));
  return [raw, ...expanded].join(' ');
}

function smartSearchMatch(item, query) {
  const q = norm(query);
  if (!q) return true;
  const hay = norm(asText(item));
  const tokens = q.split(/\s+/).filter(Boolean);
  return tokens.every(token => {
    const candidates = [token, ...(SEARCH_ALIASES[token] || [])].map(norm);
    return candidates.some(term => hay.includes(term));
  });
}

function typeOf(item) {
  return item.type || 'course';
}

// نحتفظ بكل السجلات في قاعدة البيانات، لكن لا نعرض النسخ المتطابقة للمستخدم.
// هذا يمنع تكرار نفس الفرصة/الكورس/المنصة بسبب مصادر أو استيرادات متعددة.
function uniqueDisplay(items) {
  const seen = new Set();
  return items.filter(item => {
    const type = typeOf(item);
    const title = norm(item.title || item.name);
    const org = norm(item.organization || item.platform_name || '');
    const key = `${type}::${title}::${org}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function hasCertificate(item) {
  if (item?.certificate_available === true || item?.certificate === true || item?.certificate_available === 1 || item?.certificate === 1) return true;
  const text = norm([item?.certificate_type, item?.description, item?.title, item?.name, item?.category].filter(Boolean).join(' '));
  if (!text) return false;
  return /(certificate|certification|credential|badge|accreditation|diploma|شهادة|اعتماد|دبلوم|مهني|professional)/i.test(text) && !/(no certificate|لا توجد شهادة|without certificate|بدون شهادة|not provide certificate|no certificate stated)/i.test(text);
}

function certificateKind(item) {
  if (!hasCertificate(item)) return 'none';
  const t = norm([item.certificate_type, item.title, item.description].filter(Boolean).join(' '));
  if (/professional|مهني|certified|professional certificate|credential/.test(t)) return 'professional';
  if (/academic|أكاديمي|degree|diploma|دبلوم/.test(t)) return 'academic';
  return 'completion';
}

function fundingMatch(item) {
  const f = norm(item.funding_type);
  if (state.filters.funding === 'free') return !!item.free || /free|مجاني|مجان/.test(f);
  if (state.filters.funding === 'fully') return /fully|full|كامل/.test(f);
  if (state.filters.funding === 'partial') return /partial|جزئي/.test(f);
  if (state.filters.funding === 'tuition') return !!item.tuition_covered || /tuition|رسوم/.test(f);
  return true;
}

function matches(item) {
  const q = norm(state.searchQuery);
  if (q && !smartSearchMatch(item, q)) return false;
  const f = state.filters;
  if (f.language && !norm(item.language).includes(norm(f.language))) return false;
  if (f.category && !norm([item.category, ...arr(item.categories)]).join(' ').includes(norm(f.category))) return false;
  if (f.certificate === 'none') {
    if (hasCertificate(item)) return false;
  } else if (f.certificate && certificateKind(item) !== f.certificate) return false;
  if (f.country && !norm(item.country).includes(norm(f.country))) return false;
  if (f.level && !norm([item.level, item.education_level]).join(' ').includes(norm(f.level))) return false;
  if (f.mode === 'online' && !(item.online || typeOf(item) === 'course')) return false;
  if (f.mode === 'offline' && (item.online || typeOf(item) === 'course')) return false;
  if (!fundingMatch(item)) return false;
  return true;
}

function currentItems() {
  // عند استخدام البحث، ابحث في الدليل كله بدل حصر النتائج في التبويب الذي كان مفتوحًا.
  // هذا يمنع حالة مثل: البحث عن "روسي" أثناء فتح "التطوع" = صفر نتائج،
  // بينما توجد منح وكورسات وفرص روسية فعلًا. التبويبات تظل تعمل كفلتر عندما لا يوجد بحث.
  if (state.searchQuery.trim()) {
    return uniqueDisplay([...state.opportunities, ...state.courses, ...state.platforms]).filter(matches);
  }
  if (state.activeCategory === 'platform') return uniqueDisplay(state.platforms).filter(matches);
  if (state.activeCategory === 'course') return uniqueDisplay(state.courses).filter(matches);
  if (state.activeCategory === 'under18') {
    return state.opportunities
      .filter(i => {
        const min = Number.isFinite(Number(i.age_min)) ? Number(i.age_min) : 0;
        const max = Number.isFinite(Number(i.age_max)) ? Number(i.age_max) : null;
        return min < 18 || (max !== null && max < 18);
      })
      .filter(matches);
  }
  return uniqueDisplay(state.opportunities.filter(i => state.activeCategory === 'all' || i.type === state.activeCategory)).filter(matches);
}

function sortItems(items) {
  const s = state.filters.sort;
  return [...items].sort((a, b) => {
    if (s === 'az') return norm(a.title || a.name).localeCompare(norm(b.title || b.name), 'ar');
    if (s === 'newest') return String(b.last_checked || '').localeCompare(String(a.last_checked || ''));
    if (s === 'deadline') {
      const da = a.deadline || '9999-12-31',
        db = b.deadline || '9999-12-31';
      return String(da).localeCompare(String(db));
    }
    return Number(b.verified) - Number(a.verified);
  });
}

function field(label, value) {
  if (value === undefined || value === null || value === '') return '';
  return `<div class="detail-item"><b>${escapeHtml(label)}</b><span>${escapeHtml(String(value))}</span></div>`;
}

function listSection(title, values) {
  const a = arr(values);
  if (!a.length) return '';
  return `<section class="modal-section"><h3>${escapeHtml(title)}</h3><ul>${a.map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ul></section>`;
}

function opportunityModal(item) {
  const title = item.title || item.name;
  const details = [field('الجهة', item.organization), field('الدولة', item.country), field('الفئة التعليمية', item.education_level), field('المجال', item.category), field('اللغة', item.language), field('العمر', item.age_min || item.age_max ? `${item.age_min??''}${item.age_max?` – ${item.age_max}`:'+'}` : ''), field('التمويل', item.funding_type), field('الرسوم الدراسية', item.tuition_covered ? 'مغطاة' : 'غير معلن/غير مغطاة'), field('السكن', item.accommodation ? 'متاح/مغطى' : 'غير معلن'), field('الوجبات', item.meals ? 'مغطاة' : 'غير معلن'), field('السفر', item.travel ? 'مغطى' : 'غير معلن'), field('المخصص المالي', item.stipend), field('المدة', item.duration), field('الشهادة', item.certificate ? 'متاحة' : 'غير معلنة'), field('الموعد النهائي', item.deadline || 'مفتوح/غير معلن'), field('آخر تحقق', item.last_checked)];
  els.modalContent.innerHTML = `<div class="modal-hero"><span class="badge">${ICONS[typeOf(item)]||'✨'} ${escapeHtml(LABELS[typeOf(item)]||typeOf(item))}</span>${item.verified?'<span class="verified"> ✓ مصدر موثوق</span>':''}<h2 id="modal-title">${escapeHtml(title)}</h2><p>${escapeHtml(item.description)}</p></div><section class="modal-section"><h3>المعلومات الأساسية</h3><div class="detail-grid">${details.join('')}</div></section>${listSection('شروط الأهلية',item.eligibility)}${listSection('المستندات والمتطلبات',item.requirements)}<section class="modal-section"><h3>المصدر</h3><div class="detail-grid">${field('نوع المصدر',item.source_type||'official')}${field('الرابط الرسمي',item.official_source||item.application_url)}</div></section><div class="modal-actions"><a class="primary" href="${escapeHtml(item.application_url)}" target="_blank" rel="noopener noreferrer">التقديم / التوجه للمصدر الرسمي ↗</a><a class="secondary" href="${escapeHtml(item.official_source||item.application_url)}" target="_blank" rel="noopener noreferrer">التحقق من المصدر ↗</a></div>`;
  openModal();
}

function courseModal(item) {
  els.modalContent.innerHTML = `<div class="modal-hero"><span class="badge">💻 كورس</span>${item.verified?'<span class="verified"> ✓ مصدر رسمي</span>':''}<h2 id="modal-title">${escapeHtml(item.title)}</h2><p>${escapeHtml(item.description)}</p></div><section class="modal-section"><h3>تفاصيل الكورس</h3><div class="detail-grid">${field('المنصة',item.platform_name)}${field('المجال',item.category)}${field('المستوى',item.level)}${field('اللغة',item.language)}${field('المدة',item.duration)}${field('السعر',item.price||'غير محدد')}${field('الدراسة',item.free?'مجاني':'مدفوع/حسب صفحة الكورس')}${field('الشهادة',item.certificate_available?item.certificate_type||'متاحة':'لا توجد شهادة معلنة')}${field('مساعدة مالية',item.financial_aid?'متاحة':'غير معلنة')}${field('آخر تحقق',item.last_checked)}</div></section><section class="modal-section"><h3>كيف تحصل على المجاني؟</h3><p>افتح الصفحة الرسمية للكورس وتحقق من حالة السعر والوصول قبل التسجيل. إذا كانت صفحة الكورس تعلن الوصول المجاني، ابدأ المحتوى من المصدر الرسمي. لا نعتبر الشهادة مجانية إلا إذا كان ذلك معلنًا بوضوح من الجهة.</p></section><div class="modal-actions"><a class="primary" href="${escapeHtml(item.official_url)}" target="_blank" rel="noopener noreferrer">الذهاب إلى الكورس الرسمي ↗</a><a class="secondary" href="${escapeHtml(item.source||item.official_url)}" target="_blank" rel="noopener noreferrer">المصدر ↗</a></div>`;
  openModal();
}

function platformModal(item) {
  els.modalContent.innerHTML = `<div class="modal-hero"><span class="badge">🏛️ منصة تعليمية</span>${item.verified?'<span class="verified"> ✓ موثقة</span>':''}<h2 id="modal-title">${escapeHtml(item.name)}</h2><p>${escapeHtml(item.description)}</p></div><section class="modal-section"><h3>عن المنصة</h3><div class="detail-grid">${field('الدولة',item.country||'Global')}${field('المجالات',arr(item.categories).join('، '))}${field('كورسات مجانية',item.free_courses_available?'نعم':'غير معلن')}${field('شهادات',item.certificates_available?'متاحة':'غير معلنة')}${field('مساعدة مالية',item.financial_aid_available?'متاحة':'غير معلنة')}${field('آخر تحقق',item.last_checked)}</div></section>${item.free_access_guide?`<section class="modal-section"><h3>طريقة الوصول للمحتوى المجاني</h3><p>${escapeHtml(item.free_access_guide)}</p></section>`:''}<section class="modal-section"><h3>روابط المنصة الرسمية</h3><div class="modal-actions"><a class="primary" href="${escapeHtml(item.official_url)}" target="_blank" rel="noopener noreferrer">الموقع الرسمي ↗</a>${item.courses_url?`<a class="secondary" href="${escapeHtml(item.courses_url)}" target="_blank" rel="noopener noreferrer">الكورسات ↗</a>`:''}</div></section>`;
  openModal();
}

function openModal() {
  els.modal.classList.remove('hidden');
  document.body.style.overflow = 'hidden';
}

function closeModal() {
  els.modal.classList.add('hidden');
  document.body.style.overflow = '';
}

function card(item) {
  const type = typeOf(item);
  const title = item.title || item.name;
  const source = item.organization || item.platform_name || 'منصة تعليمية';
  const verified = item.verified ? '<span class="verified">✓ موثق</span>' : '';
  const chips = [];
  if (item.country) chips.push(`🌍 ${escapeHtml(item.country)}`);
  if (item.language) chips.push(`🌐 ${escapeHtml(item.language)}`);
  if (item.online) chips.push('🖥️ أونلاين');
  if (type === 'course' && item.free) chips.push('🆓 مجاني');
  if (item.certificate_available || item.certificate) chips.push('🏅 شهادة');
  if (item.funding_type) chips.push(`💰 ${escapeHtml(item.funding_type)}`);
  if (item.deadline) chips.push(`⏳ ${escapeHtml(item.deadline)}`);
  const d = document.createElement('article');
  d.className = 'opportunity-card';
  d.innerHTML = `<div class="card-top"><span class="badge">${ICONS[type]||'✨'} ${escapeHtml(LABELS[type]||type)}</span>${verified}</div><h3 class="card-title">${escapeHtml(title)}</h3><div class="card-org">${escapeHtml(source)}</div><p class="card-summary">${escapeHtml(item.description||'لا يوجد وصف مختصر منشور.')}</p><div class="chips">${chips.map(x=>`<span class="chip">${x}</span>`).join('')}</div><div class="card-actions"><button class="details-btn" type="button">كل التفاصيل</button>${item.application_url||item.official_url?`<a class="source-btn" href="${escapeHtml(item.application_url||item.official_url)}" target="_blank" rel="noopener noreferrer">المصدر الرسمي ↗</a>`:''}</div>`;
  const openDetails = () => {
    if (type === 'platform') { window.location.href = `/platform.html?slug=${encodeURIComponent(item.slug || item.id)}`; return; }
    window.location.href = `/detail.html?type=${encodeURIComponent(type)}&id=${encodeURIComponent(item.id)}`;
  };
  d.querySelector('.details-btn').addEventListener('click', openDetails);
  d.addEventListener('click', e => {
    if (e.target.closest('a, button')) return;
    openDetails();
  });
  d.setAttribute('tabindex', '0');
  d.setAttribute('role', 'button');
  d.setAttribute('aria-label', `فتح تفاصيل ${title}`);
  d.addEventListener('keydown', e => {
    if ((e.key === 'Enter' || e.key === ' ') && !e.target.closest('a, button')) { e.preventDefault(); openDetails(); }
  });
  return d;
}

function render() {
  const filtered = sortItems(currentItems());
  const visible = filtered.slice(0, state.visibleCount);
  els.grid.innerHTML = '';
  if (!visible.length) {
    els.grid.innerHTML = '<div class="opportunity-card" style="grid-column:1/-1;text-align:center;padding:50px"><h3>لا توجد نتائج مطابقة</h3><p class="card-summary">جرّب تغيير اللغة أو المجال أو إزالة بعض الفلاتر.</p></div>';
  } else visible.forEach(i => els.grid.appendChild(card(i)));
  const label = state.searchQuery.trim() ? 'نتيجة بحث' : state.activeCategory === 'platform' ? 'منصة' : state.activeCategory === 'course' ? 'كورس' : state.activeCategory === 'under18' ? 'فرصة مناسبة لمن هم دون 18' : 'فرصة';
  els.summary.textContent = `عرض ${visible.length} من أصل ${filtered.length} ${label}`;
  els.searchCount.textContent = state.searchQuery ? `${filtered.length} نتيجة` : '';
  els.more.classList.toggle('hidden', visible.length >= filtered.length);
  const active = [];
  for (const [k, v] of Object.entries(state.filters))
    if (v && k !== 'sort') active.push(v);
  if (state.searchQuery) active.unshift(`بحث: ${state.searchQuery}`);
  els.active.textContent = active.join(' · ');
}

function populateFilters() {
  const all = uniqueDisplay([...state.courses, ...state.opportunities, ...state.platforms]);
  const fill = (id, values) => {
    const el = $(id),
      current = el.value,
      uniq = [...new Set(values.flatMap(arr).filter(Boolean).map(String))].sort((a, b) => a.localeCompare(b));
    el.innerHTML = '<option value="">الكل</option>' + uniq.map(v => `<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`).join('');
    if ([...el.options].some(o => o.value === current)) el.value = current;
  };
  fill('filter-language', all.map(x => x.language));
  fill('filter-category', all.map(x => [x.category, ...arr(x.categories)]));
  fill('filter-country', all.map(x => x.country));
  fill('filter-level', all.map(x => [x.level, x.education_level]));
}

function reset() {
  state.searchQuery = '';
  state.activeCategory = 'all';
  state.visibleCount = 12;
  state.filters = {
    language: '',
    category: '',
    certificate: '',
    country: '',
    funding: '',
    mode: '',
    level: '',
    sort: 'relevance'
  };
  els.search.value = '';
  document.querySelectorAll('.filter-grid select').forEach(x => x.value = '');
  document.querySelectorAll('.tab-btn').forEach((x, i) => x.classList.toggle('active', i === 0));
  const filterToggle = $('toggle-filters');
  const filterGrid = $('filter-grid');
  if (filterToggle && filterGrid) {
    filterGrid.classList.remove('open');
    filterToggle.setAttribute('aria-expanded', 'false');
  }
  render();
}

function bind() {
  const debouncedRender = debounce(() => render(), 220);
  els.search.addEventListener('input', e => {
    state.searchQuery = e.target.value;
    state.visibleCount = 12;
    debouncedRender();
    showSuggestions();
  });
  const filterToggle = $('toggle-filters');
  const filterGrid = $('filter-grid');
  if (filterToggle && filterGrid) {
    filterToggle.addEventListener('click', () => {
      const isOpen = filterGrid.classList.toggle('open');
      filterToggle.setAttribute('aria-expanded', String(isOpen));
    });
  }
  els.tabs.addEventListener('click', e => {
    const b = e.target.closest('[data-category]');
    if (!b) return;
    state.activeCategory = b.dataset.category;
    state.visibleCount = 12;
    document.querySelectorAll('.tab-btn').forEach(x => x.classList.toggle('active', x === b));
    render()
  });
  [
    ['filter-language', 'language'],
    ['filter-category', 'category'],
    ['filter-certificate', 'certificate'],
    ['filter-country', 'country'],
    ['filter-funding', 'funding'],
    ['filter-mode', 'mode'],
    ['filter-level', 'level'],
    ['filter-sort', 'sort']
  ].forEach(([id, key]) => $(id).addEventListener('change', e => {
    state.filters[key] = e.target.value;
    state.visibleCount = 12;
    render()
  }));
  els.more.addEventListener('click', () => {
    state.visibleCount += 12;
    render()
  });
  $('clear-filters').addEventListener('click', reset);
  document.querySelectorAll('[data-quick-search]').forEach(btn => btn.addEventListener('click', () => {
    state.searchQuery = btn.dataset.quickSearch || '';
    els.search.value = state.searchQuery;
    state.visibleCount = 12;
    render();
    showSuggestions();
    els.search.focus();
  }));
  els.search.addEventListener('keydown', e => {
    if (e.key === 'Escape') {
      const box = $('search-suggestions');
      if (box) box.classList.add('hidden');
      els.search.setAttribute('aria-expanded', 'false');
    }
  });
  document.addEventListener('click', e => {
    const shell = document.querySelector('.search-shell');
    if (shell && !shell.contains(e.target)) {
      const box = $('search-suggestions');
      if (box) box.classList.add('hidden');
      els.search.setAttribute('aria-expanded', 'false');
    }
  });
  document.addEventListener('keydown', e => {
    if (false) { e.preventDefault(); }
  });
  els.modal.addEventListener('click', e => {
    if (e.target.hasAttribute('data-close-modal')) closeModal()
  });
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape') closeModal()
  });
}
