async function fetchAllPages(url, pageSize = 100) {
  let page = 1,
    total = Infinity,
    out = [];
  for (let guard = 0; guard < 1000 && out.length < total; guard++, page++) {
    const sep = url.includes('?') ? '&' : '?';
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 7000);
    let r;
    try {
      r = await fetch(`${url}${sep}page=${page}&page_size=${pageSize}`, { headers: { Accept: 'application/json' }, signal: controller.signal });
    } finally { clearTimeout(timeout); }
    if (!r.ok) throw Error(`${r.status} ${url}`);
    const j = await r.json();
    const batch = Array.isArray(j.results) ? j.results : [];
    total = Number.isFinite(Number(j.total)) ? Number(j.total) : out.length + batch.length;
    out.push(...batch);
    if (!batch.length || out.length >= total || batch.length < pageSize) break;
  }
  return out;
}
async function fetchLive(type) {
  try {
    const r = await fetch(`/api/live?type=${type}&limit=100`, {
      headers: {
        Accept: 'application/json'
      }
    });
    if (!r.ok) return [];
    const j = await r.json();
    return Array.isArray(j.results) ? j.results : [];
  } catch (e) {
    console.warn(`Live ${type} API unavailable.`, e);
    return [];
  }
}
async function load() {
  renderSkeletons();
  // اعرض النسخة المضمنة فورًا. إذا تعطل API أو تأخر، لن تظهر الصفحة فارغة.
  const embedded = FALLBACK_DATA;
  state.opportunities = Array.isArray(embedded.opportunities) ? embedded.opportunities : [];
  state.courses = Array.isArray(embedded.courses) ? embedded.courses : [];
  state.platforms = Array.isArray(embedded.platforms) ? embedded.platforms : [];
  populateFilters();
  updateCounters();
  render();

  try {
    const [opportunities, courses, platforms] = await Promise.all([
      fetchAllPages('/api/opportunities?type=all'),
      fetchAllPages('/api/courses'),
      fetchAllPages('/api/platforms')
    ]);
    // لا نستبدل البيانات المضمنة بصفوف فارغة. نستخدم API فقط عندما يعيد بيانات فعلية.
    if (Array.isArray(opportunities) && opportunities.length) state.opportunities = opportunities;
    if (Array.isArray(courses) && courses.length) state.courses = courses;
    if (Array.isArray(platforms) && platforms.length) state.platforms = platforms;
    state.courses = [...(state.courses || []), ...ZAAD_LANGUAGE_CERT_COURSES.filter(add => !(state.courses || []).some(x => String(x.slug||'') === String(add.slug)))];
    populateFilters();
    updateCounters();
    render();
  } catch (e) {
    console.warn('API unavailable; continuing with embedded catalog.', e);
    // Never leave the user on a loading state when the API is unavailable.
    populateFilters();
    updateCounters();
    render();
  }
}
function updateCounters() {
  const uniqueOppCount = uniqueDisplay(state.opportunities).length;
  const uniqueCourseCount = uniqueDisplay(state.courses).length;
  const uniquePlatformCount = uniqueDisplay(state.platforms).length;
  const total = uniqueOppCount + uniqueCourseCount;
  const free = uniqueDisplay(state.courses).filter(x => x.free).length + uniqueDisplay(state.opportunities).filter(x => /free|مجاني|مجان/i.test(String(x.funding_type || ''))).length;
  els.total.textContent = `${uniqueOppCount} فرصة + ${uniqueCourseCount} كورس + ${uniquePlatformCount} منصة`;
  $('hero-total').textContent = total;
  $('hero-platforms').textContent = uniquePlatformCount;
  $('hero-free').textContent = free;
}

$('current-year').textContent = new Date().getFullYear();
// اعرض الكتالوج المضمن أولًا قبل أي اتصال بالـ API.
// حتى لو فشل عنصر في الواجهة، لن تختفي بيانات الفرص والكورسات.
load();
